// 4.1 @writes @data: работа QA-AUTO с неоплаченным инвойсом → Items → Add Item → Save → toast «Item added successfully» +
//      «Invoice INV-… was updated to match» (номер инвойса). Поведение синхронизации не менялось (решение Sprint 2, решение пользователя 17.11:
//      принято по требованиям). Очистка: работа → Cancelled (позиции QA-AUTO остаются в отменённой работе). SMS/email блокируются.
// 4.2 ПРОПУЩЕН: у оплаченного инвойса пункт не должен попадать в счёт — оплаченных счетов в Pre-Prod нет (17.11), не проверено.
// Не сверено с сайтом при записи: у новой работы с позицией появляется инвойс (кнопка «Edit Invoice» как у JOB-0001 на скриншоте 687146-toast-desktop.png).
import { test, expect, BrowserContext, Page } from '@playwright/test';
import { addManualItem } from '../pricebook/pricebook-helpers';
import { blockMessaging, cancelJob, createJobWithBalance, openRoleContext, stamp } from './payments-helpers';

test.describe.configure({ mode: 'serial' });

test.describe('Job → Add Item: toast names the invoice (#687146)', () => {
  let context: BrowserContext;
  let page: Page;
  let jobUrl: string | null = null;
  let messaging: string[] = [];

  test.beforeAll(async ({ browser }, testInfo) => {
    test.setTimeout(150_000);
    ({ context, page } = await openRoleContext(browser, testInfo));
    messaging = await blockMessaging(page);
  });

  test.afterAll(async () => {
    await cancelJob(page, jobUrl);
    await context?.close();
  });

  test.afterEach(() => {
    expect(messaging, 'запросов отправки SMS/email быть не должно').toEqual([]);
  });

  test('QA-AUTO: Add Item on a job with an unpaid invoice → toast «Invoice INV-… was updated to match» #687146 @desktop @writes @data', async () => {
    test.setTimeout(150_000);
    jobUrl = await createJobWithBalance(page, 'invoice-toast', { ticket: '#687146' });

    const toast = page.locator('li, [role="status"]').filter({ hasText: /Invoice INV-\d+ was updated to match/ });
    // дождаться, пока уйдёт toast от первой позиции (её добавил createJobWithBalance), чтобы проверять именно вторую
    await expect(toast).toHaveCount(0, { timeout: 30_000 });
    await expect(page.getByRole('button', { name: /Edit Invoice/ }), 'у работы есть инвойс').toBeVisible();

    await addManualItem(page, { name: `QA-AUTO invoice-line ${stamp()}`, price: '1' });

    await expect(toast.first()).toBeVisible({ timeout: 15_000 });
    await expect(toast.first()).toContainText('Item added successfully');
    await expect(toast.first()).toContainText(/Invoice INV-\d{4,} was updated to match/);
  });

  test.skip('Add Item on a job with a PAID invoice → the invoice is not changed #687146 @desktop', async () => {
    // Не проверено 17.11: оплаченных счетов в Pre-Prod нет. Включить, когда появится работа с оплаченным инвойсом.
  });
});
